(() => {
  'use strict';

  var loaderScript = document.getElementById('amd-loader');
  var configUrl = loaderScript.getAttribute('data-config');
  var loaderUrl = loaderScript.getAttribute('data-main') || loaderScript.getAttribute('src');
  var loaderDirectoryIndex = loaderUrl.lastIndexOf('loader/');
  var jsBaseUrl = loaderDirectoryIndex === -1 ? '' : loaderUrl.substring(0, loaderDirectoryIndex);
  var vendorScript = document.querySelector('script[src*="/loader/vendor.min.js"], script[src*="/loader/vendor.es5.min.js"]');
  var sharedLoaderUrl = vendorScript ? vendorScript.src : loaderUrl;
  var sharedLoaderDirectoryIndex = sharedLoaderUrl.lastIndexOf('loader/');
  var sharedJsBaseUrl = sharedLoaderDirectoryIndex === -1 ? jsBaseUrl : sharedLoaderUrl.substring(0, sharedLoaderDirectoryIndex);
  var locale = document.documentElement.getAttribute('lang') || 'en-US';
  var bundle = loaderScript.getAttribute('data-bundle');
  var configErrorDialog;
  window.require.config({
    baseUrl: jsBaseUrl,
    paths: {
      text: "".concat(sharedJsBaseUrl, "lib/text/text"),
      json: "".concat(sharedJsBaseUrl, "lib/text/json"),
      css: "".concat(sharedJsBaseUrl, "lib/require-css/css"),
      lodash: "".concat(sharedJsBaseUrl, "../node_modules/lodash/lodash"),
      core: "".concat(sharedJsBaseUrl, "../node_modules/@oat-sa/tao-core-sdk/dist/core"),
      taoCss: "".concat(sharedJsBaseUrl, "../css"),
      i18ntr: "".concat(sharedJsBaseUrl, "../locales/").concat(locale)
    }
  });
  var loadController = () => {
    var controllerOptions = {};
    var controllerPath = loaderScript.getAttribute('data-controller');
    var params = loaderScript.getAttribute('data-params');
    try {
      controllerOptions = JSON.parse(params);
    } catch (err) {
      controllerOptions = {};
    }
    window.require([controllerPath], controller => {
      var startController = () => {
        if (!window.started) {
          window.started = true;
          controller.start(controllerOptions);
        }
      };
      document.addEventListener('readystatechange', startController, false);
      if (document.readyState === 'complete') {
        startController();
      }
    });
  };
  var onConfigLoaded = () => {
    if (configErrorDialog) {
      configErrorDialog.destroy();
    }
    if (!window.loadBundles) {
      window.loaded = {};
      window.loadBundles = function () {
        var bundles = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : [];
        var uniqueBundles = bundles.concat(window.bundles).filter((item, index, bundleList) => item && bundleList.indexOf(item) === index && window.loaded[item] !== true);
        window.require(uniqueBundles, () => {
          uniqueBundles.forEach(item => {
            window.loaded[item] = true;
          });
          loadController();
        });
      };
    }
    if (bundle || window.bundles && window.bundles.length) {
      window.loadBundles([bundle]);
    } else {
      loadController();
    }
  };
  window.require(['loader/configRetry'], configRetryDialog => {
    configErrorDialog = configRetryDialog();
    window.require([configUrl], onConfigLoaded, () => {
      configErrorDialog.show();
    });
  });
})();
define("loader/bootstrap", function(){});

